// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzzed params: from address, array of to addresses, array of values
    function testFuzz_property(address from, address to0, address to1, uint256 v0, uint256 v1, uint256 len) public {
        // keep len either 1 or 2 to keep test simple but still fuzzed
        len = bound(len, 1, 2);

        // build _tos and v arrays with fuzzed entries
        address[] memory _tos = new address[](len);
        uint[] memory vals = new uint[](len);
        _tos[0] = to0;
        vals[0] = v0;
        if (len == 2) {
            _tos[1] = to1;
            vals[1] = v1;
        }

        // deploy a recorder that exposes a function matching the selector "transferFrom(address,address,uint256)"
        Recorder rec = new Recorder();

        // call transfer on c, passing recorder address as caddress
        bool ok;
        try c.transfer(from, address(rec), _tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any non-empty _tos, the correct contract will have invoked
        // transferFrom(address,address,uint256) on the callee for each element; our recorder
        // records how many well-formed transferFrom calls it received.
        // We assert that the recorder saw exactly `len` decoded transferFrom calls.
        // This holds for the reference implementation for all inputs; the mutant that
        // uses a wrong selector will cause the recorder to see 0 decoded transferFrom calls
        // for some inputs, breaking this assertion.

        // read recorder state (public getter)
        uint received = rec.count();

        assertTrue(received == len);
    }
}

// Recorder that exposes the exact signature the reference contract encodes with selector
contract Recorder {
    // store decoded calls
    uint256 public calls;
    address[] public froms;
    address[] public tos;
    uint256[] public vals;

    // The function signature must match: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external {
        calls += 1;
        froms.push(from);
        tos.push(to);
        vals.push(value);
    }

    // helper getter for count (calls is public but keep explicit for clarity)
    function count() external view returns (uint256) {
        return calls;
    }
}
